def read(p):
 with gzip.open(p,'rt') if str(p).endswith('.gz') else open(p) as f:return json.load(f)
rows=read(O/'cells.json');sums=read(O/'summary.json');traces=read(O/'tradeoff_points.json.gz');front=read(O/'validation_frontier_test_points.json.gz')
C=['baseline','saliency','nearest'];COL={'baseline':'#64748b','saliency':'#d97706','nearest':'#1676c5'};LABEL={'baseline':'No explanation','saliency':'Saliency','nearest':'1 nearest neighbour'}
NAMES={'qwen':'Qwen 27B','gemma':'Gemma 31B','mistral':'Mistral 119B','olmo':'OLMo 32B','glm':'GLM','qwen122':'Qwen 122B','claude4.5-sonnet':'Claude Sonnet','claude4.8-opus':'Claude Opus','gpt-4o':'GPT-4o','gpt-astra':'GPT Astra'}
def selected(data,scope='combined',model='ALL'):
 return [r for r in data if ((scope=='combined' and r['scope']!='common_valid') or r['scope']==scope) and (model=='ALL' or r['model']==model)]
def trace(data,c):
 return np.array([[np.mean([r[k] for r in data if r['condition']==c and r['beta_index']==i])*100 for k in ['recall','precision','f1']] for i in range(41)])
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.16,'savefig.facecolor':'white'})
def panel(ax,scope='combined',model='ALL'):
 t=selected(traces,scope,model);s=selected(sums,scope,model)
 for c in C:
  xy=trace(t,c);ax.plot(xy[:,0],xy[:,1],color=COL[c],lw=2,label=LABEL[c]);ax.scatter(xy[20,0],xy[20,1],marker='*',s=230,c=COL[c],edgecolors='white',lw=.7,zorder=5)
  f=next(r for r in s if r['condition']==c and r['policy']=='fixed_both50' and r['model']==model)
  ax.scatter(f['recall']*100,f['precision']*100,marker='D',s=45,c=COL[c],edgecolors='white',lw=.7,zorder=4)
 ax.set_xlabel('Mean test recall (%)');ax.set_ylabel('Mean test precision (%)')
 return ax
fig,axes=plt.subplots(1,2,figsize=(13,6.4))
fig.subplots_adjust(left=.065,right=.985,top=.81,bottom=.23,wspace=.2)
panel(axes[0]);axes[0].set_title('All 500 combinations\nLocal full-test + API available-case estimates',fontsize=12)
panel(axes[1],'common_valid');axes[1].set_title('Identical cases across all 10 judges\n500-combination sensitivity analysis',fontsize=12)
fig.suptitle('Control-selected precision–recall trade-offs on test data',fontsize=16)
handles,labels=axes[0].get_legend_handles_labels();fig.legend(handles,labels,loc='lower center',bbox_to_anchor=(.5,.015),ncol=3,frameon=False)
fig.text(.5,.115,'★ Control-selected F1 operating point    ◆ Both thresholds fixed at 50',ha='center',fontsize=10)
fig.text(.5,.08,'Lines: control-validation Fβ choices (β = 0.1 … 10); no test-based selection or pruning.',ha='center',fontsize=10)
for ext in ['png','pdf','svg']:fig.savefig(O/f'frontier_overview.{ext}',dpi=180)
plt.close(fig)
fig,axes=plt.subplots(2,5,figsize=(20,9))
fig.subplots_adjust(left=.05,right=.99,top=.88,bottom=.18,wspace=.34,hspace=.4)
for ax,m in zip(axes.flat,NAMES):panel(ax,'combined',m);ax.set_title(NAMES[m],fontsize=12)
fig.suptitle('Each judge: control-selected trade-offs evaluated on test',fontsize=18)
fig.text(.5,.09,'Each point averages 50 backbone × dataset combinations. ★ Control-selected F1 point; ◆ fixed 50/50. Control chooses all cutoffs; explanations use the identical pairs.',ha='center',fontsize=11)
fig.legend(handles,labels,loc='lower center',bbox_to_anchor=(.5,.02),ncol=3,frameon=False)
for ext in ['png','pdf']:fig.savefig(O/f'frontier_by_judge.{ext}',dpi=170)
plt.close(fig)

# A compact, self-contained report: no network requests or external dependencies.
cellkey=lambda r:'|'.join(r[k] for k in ['scope','model','backbone','dataset','condition'])
data={}
for r in rows:
 key=cellkey(r)
 if key not in data:data[key]={'scope':r['scope'],'model':r['model'],'backbone':r['backbone'],'dataset':r['dataset'],'condition':r['condition'],'n':r['test_n'],'v':r['validation_n'],'trace':[],'front':[]}
 data[key][r['policy']]={k:r[k] for k in ['precision','recall','f1','accuracy','probe_threshold','judge_threshold','validation_f1','validation_rejected','test_rejected']}
for r in traces:data[cellkey(r)]['trace'].append([r['recall'],r['precision'],r['f1'],r['probe_threshold'],r['judge_threshold']])
for r in front:data[cellkey(r)]['front'].append([r['recall'],r['precision'],r['f1'],r['probe_threshold'],r['judge_threshold'],r['validation_recall'],r['validation_precision'],r['validation_accepted']])
payload=json.dumps(list(data.values()),separators=(',',':')).replace('</','<\\/')
page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fixed 50 and control-tuned evaluation</title><style>
body{font:15px/1.55 system-ui,sans-serif;color:#182c42;background:#f4f7fa;margin:0}main{max-width:1400px;margin:auto;padding:32px}h1{font-size:30px;margin-bottom:8px}h2{margin-top:30px}p{max-width:1100px}.card{background:white;padding:22px;border:1px solid #dce3ec;border-radius:12px;margin:18px 0}.controls{display:flex;flex-wrap:wrap;gap:18px;align-items:end}label{display:grid;gap:6px;font-weight:600}select{padding:9px;min-width:155px;border:1px solid #aebdcc;border-radius:5px;background:white}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{padding:9px;border-bottom:1px solid #e3e8ed;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:#edf2f7;font-size:13px}.scroll{overflow:auto}.small{font-size:13px;color:#526579}.badge{padding:4px 8px;border-radius:5px;background:#e7f0fa}svg{width:100%;height:auto}.legend{display:flex;gap:22px;flex-wrap:wrap}img{width:100%;height:auto}a{color:#1666aa}summary{cursor:pointer;font-weight:600}code{background:#edf2f7;padding:2px 4px}</style></head><body><main>
<h1>Two tests: fixed 50/50 and control-tuned thresholds</h1>
<p>Five backbones × ten judges × ten datasets = <b>500 combinations</b>, each evaluated with no explanation, saliency and one nearest neighbour. Existing predictions only; no new inference. For each backbone–judge–dataset combination, both thresholds are selected using CONTROL validation scores only, then frozen unchanged across control, saliency and NN. Different judges may retain different control-selected thresholds.</p>
<div class="card"><div class="controls"><label>Evaluation population<select id="scope"><option value="combined">All results (original scopes)</option><option value="common_valid">Same valid cases across all judges</option><option value="local_full">Local judges: full-test estimates</option><option value="api_matched">API judges: available cases</option></select></label><label>Judge<select id="model"><option value="ALL">All judges</option></select></label><label>Backbone<select id="backbone"><option value="ALL">All backbones</option></select></label><label>Dataset<select id="dataset"><option value="ALL">All datasets</option></select></label></div><p class="small" id="coverage"></p></div>
<div class="card"><h2>Held-out test results</h2><p>Macro means over the selected combinations; every metric below is a percentage. “Control-tuned” maximises weighted CONTROL validation F1 over the probe and judge threshold grid. Explanations never select their own cutoffs. No rows are excluded for selecting a zero cutoff.</p><div class="scroll" id="table"></div><p id="gains"></p><p class="small" id="bypass"></p></div>
<div class="card"><h2>Control-selected trade-offs, measured on test</h2><p>Each line varies the CONTROL validation objective from precision emphasis to recall emphasis (Fβ, β 0.1–10). <b>Stars</b> mark the maximum-validation-F1 policy from the table; <b>diamonds</b> mark fixed 50/50. At each point, search both thresholds on control only, then apply the SAME pair to all three explanation conditions for that judge, backbone and dataset. Test results never choose or remove points.</p><div class="legend"><span style="color:#64748b">● No explanation</span><span style="color:#d97706">● Saliency</span><span style="color:#1676c5">● 1 nearest neighbour</span></div><svg id="chart" viewBox="0 0 1000 560" role="img" aria-label="Test precision recall tradeoff"></svg><p class="small">Higher and farther right is better. Lines connect corresponding validation preferences; test performance need not be monotonic. These are held-out trade-off traces anchored on control, not independently optimised explanation frontiers or an envelope selected to look best on test. Averages are of cell metrics, so mean F1 is not the harmonic mean of mean precision and mean recall.</p>
<details id="individual"><summary>Full control-validation Pareto set for this individual combination</summary><p class="small">Available when one judge, backbone and dataset are selected. These points exhaust the nondominated CONTROL validation grid after duplicate decisions are resolved by the frozen tie rule. Their test coordinates are shown without test pruning. Hover for thresholds and validation support.</p><svg id="fullchart" viewBox="0 0 1000 560"></svg></details></div>
<div class="card"><h2>Per-judge results</h2><p class="small">Uses the selected population, backbone and dataset filters. Each condition shows precision / recall / F1 (%).</p><div class="scroll" id="judges"></div></div>
<details class="card"><summary>Methods, coverage and interpretation</summary>
<p>The two main tests are exactly: (1) probe ≥0.5 AND judge ≥50; (2) jointly maximise CONTROL validation F1 and freeze both cutoffs across conditions. The tuned probe candidates are the original validation-derived grid, including the reject-all endpoint. Judge candidates are integers 0–100 plus101 for reject-all. Equal CONTROL F1 within10⁻¹² chooses the highest probe threshold, then highest judge cutoff. No requirement for an active judge or a minimum number of positive predictions is added. Validation-equivalent probe columns retain their highest original threshold.</p>
<p>Local results use original inverse inclusion probabilities and exact full-test class totals. API results retain cases with valid answers in all three conditions for that API model, with original weights; they are conditional on that availability. The combined500-cell mean mixes these two estimands and is descriptive. The common-valid view retains identical cases across all ten judges and all three conditions, allowing a stricter matched comparison; it does not correct non-random API missingness.</p>
<p>There are500 validation and500 test sampled cases per backbone–dataset pair before API exclusions. These are50,000 backbone-case records, not50,000 necessarily unique texts. Cases repeated across judges or backbones are not independent observations. All results here are weighted point estimates; the frontier is not a confidence band. Data and plots are exploratory follow-up analyses of an already inspected test set.</p>
<p>Zero judge cutoffs remain legitimate probe-only endpoints. A nonzero cutoff may also make no vetoes. The table reports zero cutoffs and actual validation veto activity separately. At a fixed referral gate the judge can only remove probe flags.</p>
<p>Verification replays3,000 fixed-policy condition cells and1,000 tuned CONTROL cells against previous outputs, checks source hashes, verifies that all conditions share both thresholds and referral sets, verifies that zero cutoffs give identical predictions, and checks that β=1 exactly reproduces the control-tuned F1 table. The older active-judge constrained and independent-explanation threshold policies are not used. Earlier reports are preserved separately.</p></details>
<div class="card"><h2>Downloads</h2><p><a href="control_thresholds.html">All500 shared threshold pairs</a> · <a href="control_thresholds.csv">Threshold CSV</a> · <a href="summary.csv">Summary table CSV</a> · <a href="cell_results.csv">Every combination and both threshold pairs</a> · <a href="frontier_overview.pdf">Frontier PDF</a> · <a href="frontier_by_judge.pdf">Per-judge plots PDF</a> · <a href="validation_frontier_test_points.csv.gz">Full control-selected frontier points</a> · <a href="COMPLETED.json">Verification manifest</a></p></div>
</main><script>const D=__DATA__;const names=__NAMES__;const colors={baseline:'#64748b',saliency:'#d97706',nearest:'#1676c5'},labels={baseline:'No explanation',saliency:'Saliency',nearest:'1 nearest neighbour'},conds=Object.keys(colors);const $=id=>document.getElementById(id);const mean=a=>a.reduce((x,y)=>x+y,0)/a.length;const fmt=x=>(100*x).toFixed(2);
for(const k of ['model','backbone','dataset']){for(const v of [...new Set(D.map(r=>r[k]))]){const o=document.createElement('option');o.value=v;o.textContent=k==='model'?names[v]:v;$(k).appendChild(o)}}
function filter(ignoreModel=false){let scope=$('scope').value;return D.filter(r=>(scope==='combined'?r.scope!=='common_valid':r.scope===scope)&&['model','backbone','dataset'].every(k=>(ignoreModel&&k==='model')||$(k).value==='ALL'||r[k]===$(k).value))}
function chart(id,rs,full=false){const svg=$(id);if(!rs.length){svg.innerHTML='';return}let lines=conds.map(c=>{let a=rs.filter(r=>r.condition===c);return {c,points:full?(a.length===1?a[0].front:[]):Array.from({length:41},(_,i)=>[mean(a.map(r=>r.trace[i][0])),mean(a.map(r=>r.trace[i][1]))]),fixed:[mean(a.map(r=>r.fixed_both50.recall)),mean(a.map(r=>r.fixed_both50.precision))],star:[mean(a.map(r=>r.control_validation_f1.recall)),mean(a.map(r=>r.control_validation_f1.precision))]}});let pts=lines.flatMap(l=>[...l.points,l.fixed,l.star]).filter(p=>p.every(Number.isFinite));if(!pts.length){svg.innerHTML='';return}let xmin=Math.max(0,Math.min(...pts.map(p=>p[0]))-.03),xmax=Math.min(1,Math.max(...pts.map(p=>p[0]))+.03),ymin=Math.max(0,Math.min(...pts.map(p=>p[1]))-.03),ymax=Math.min(1,Math.max(...pts.map(p=>p[1]))+.03);if(xmax-xmin<.02)xmax=xmin+.02;if(ymax-ymin<.02)ymax=ymin+.02;let X=x=>85+865*(x-xmin)/(xmax-xmin),Y=y=>470-420*(y-ymin)/(ymax-ymin);let s='<rect x="0" y="0" width="1000" height="560" fill="white"/>';for(let i=0;i<=5;i++){let x=xmin+(xmax-xmin)*i/5,y=ymin+(ymax-ymin)*i/5;s+=`<path d="M${X(x)} 50V470 M85 ${Y(y)}H950" stroke="#e3e8ed"/><text x="${X(x)}" y="495" text-anchor="middle" font-size="14">${(x*100).toFixed(1)}</text><text x="75" y="${Y(y)+5}" text-anchor="end" font-size="14">${(y*100).toFixed(1)}</text>`}for(const l of lines){s+=`<polyline points="${l.points.map(p=>`${X(p[0])},${Y(p[1])}`).join(' ')}" fill="none" stroke="${colors[l.c]}" stroke-width="${full?1.2:2.5}" opacity=".85"/>`;l.points.forEach((p,i)=>{s+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="${full?3:2}" fill="${colors[l.c]}"><title>${labels[l.c]}: recall ${fmt(p[0])}, precision ${fmt(p[1])}${full?`; probe ${p[3].toPrecision(5)}, judge ${p[4]}, validation positives ${p[7]}`:`; beta ${(10**(-1+i/20)).toPrecision(3)}`}</title></circle>`});s+=`<text x="${X(l.star[0])}" y="${Y(l.star[1])+8}" fill="${colors[l.c]}" stroke="white" stroke-width=".7" font-size="29" text-anchor="middle">★<title>${labels[l.c]} control-selected F1 point</title></text><text x="${X(l.fixed[0])}" y="${Y(l.fixed[1])+7}" fill="${colors[l.c]}" stroke="white" stroke-width=".5" font-size="23" text-anchor="middle">◆<title>${labels[l.c]} fixed 50/50</title></text>`}s+='<text x="520" y="540" text-anchor="middle" font-size="17">Test recall (%)</text><text transform="translate(23 265) rotate(-90)" text-anchor="middle" font-size="17">Test precision (%)</text>';svg.innerHTML=s}
function update(){const rs=filter();if(!rs.length){$('table').innerHTML='<p>No judges in this population match the filter.</p>';$('judges').innerHTML='';$('chart').innerHTML='';$('coverage').textContent='';$('gains').textContent='';$('bypass').textContent='';return}let n=rs.length/3;let base=rs.filter(r=>r.condition==='baseline');$('coverage').textContent=`${n} combinations; ${base.reduce((s,r)=>s+r.n,0).toLocaleString()} test-case evaluations per condition (includes repeated cases across judges). Test cases per combination: ${Math.min(...base.map(r=>r.n))}–${Math.max(...base.map(r=>r.n))}.`;let t='<table><tr><th>Test / explanation</th><th>Precision</th><th>Recall</th><th>F1</th><th>Accuracy</th></tr>';let gains=[];for(const p of ['fixed_both50','control_validation_f1']){for(const c of conds){let a=rs.filter(r=>r.condition===c);t+=`<tr><td>${p==='fixed_both50'?'Fixed 50/50':'Control-tuned'} · ${labels[c]}</td>${['precision','recall','f1','accuracy'].map(k=>`<td>${fmt(mean(a.map(r=>r[p][k])))}</td>`).join('')}</tr>`}let a=rs.filter(r=>r.condition==='nearest'),b=rs.filter(r=>r.condition==='baseline'),delta=100*(mean(a.map(r=>r[p].f1))-mean(b.map(r=>r[p].f1)));gains.push(`${p==='fixed_both50'?'Fixed50/50':'Control tuning'}: NN − control F1 ${delta>=0?'+':''}${delta.toFixed(3)} points`)}$('table').innerHTML=t+'</table>';$('gains').textContent=gains.join(' · ');$('bypass').textContent='Tuned zero judge cutoffs: '+conds.map(c=>{let a=rs.filter(r=>r.condition===c);return `${labels[c]} ${a.filter(r=>r.control_validation_f1.judge_threshold===0).length}/${a.length}; no validation vetoes ${a.filter(r=>r.control_validation_f1.validation_rejected===0).length}/${a.length}`}).join(' | ');chart('chart',rs);let single=n===1;$('individual').style.display=single?'block':'none';if(single)chart('fullchart',rs,true);let all=filter(true),j='<table><tr><th>Judge / test</th>'+conds.map(c=>`<th>${labels[c]}<br>P / R / F1</th>`).join('')+'<th>NN − control F1</th></tr>';for(const m of [...new Set(all.map(r=>r.model))])for(const p of ['fixed_both50','control_validation_f1']){let vals=conds.map(c=>{let a=all.filter(r=>r.model===m&&r.condition===c);return ['precision','recall','f1'].map(k=>mean(a.map(r=>r[p][k])))});j+=`<tr><td>${names[m]} · ${p==='fixed_both50'?'50/50':'tuned'}</td>${vals.map(v=>'<td>'+v.map(fmt).join(' / ')+'</td>').join('')}<td>${((vals[2][2]-vals[0][2])*100).toFixed(3)}</td></tr>`}$('judges').innerHTML=j+'</table>'}
for(const k of ['scope','model','backbone','dataset'])$(k).addEventListener('change',update);update();</script></body></html>'''
page=page.replace('__DATA__',payload).replace('__NAMES__',json.dumps(NAMES));(O/'report.html').write_text(page)
